const ctx = $('Analyser le contexte').first().json;
const testResults = ctx.testResults;

const results = (testResults && testResults.results) || [];
const allPassed = Boolean(testResults) && testResults.allPassed === true && results.length > 0;

const recap = results
  .map(r => (r.passed ? '- [x] ' : '- [ ] ') + r.name + (r.error ? ' — ' + r.error : ''))
  .join('\n');

return [{
  json: {
    done: allPassed,
    testCount: results.length,
    recap: recap || '(aucun resultat de test recu — .n8ntest absent ou mot-cle non suivi de tests)',
  },
}];
